<?php
namespace app\controller;
use app\BaseController;use think\facade\Db;use think\facade\Session;
class RefundRequest extends BaseController{
 private function uid():int{return (int)Session::get('lumen_user_id');}
 private function guard(){return $this->uid()?null:redirect('/user/login');}
 public function apply($id){if($g=$this->guard())return$g;$uid=$this->uid();$id=(int)$id;$reason=mb_substr(trim((string)input('post.reason','')),0,500);try{Db::transaction(function()use($uid,$id,$reason){$o=Db::name('recharge_orders')->where('id',$id)->where('user_id',$uid)->lock(true)->find();if(!$o||$o['status']!=='credited'||empty($o['provider_trade_no']))throw new \RuntimeException('该订单不可申请退款');if(Db::name('refund_orders')->where('recharge_order_id',$id)->whereIn('status',['requested','approved','provider_processing','needs_reconcile'])->find())throw new \RuntimeException('该订单已有退款申请或退款正在处理');$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$id)->lock(true)->find();if(!$lot||!(int)$lot['refundable']||(int)$lot['paid_quota']<=0||(int)$lot['paid_remaining']<=0)throw new \RuntimeException('该订单当前没有可退金额');$amount=intdiv((int)$lot['paid_amount_cents']*(int)$lot['paid_remaining'],(int)$lot['paid_quota']);$amount=min($amount,max(0,(int)$o['amount_cents']-(int)$o['refund_amount_cents']));if($amount<=0)throw new \RuntimeException('可退款金额不足 0.01 元');$now=date('Y-m-d H:i:s');Db::name('refund_orders')->insert(['refund_no'=>'RR'.date('YmdHis').strtoupper(bin2hex(random_bytes(5))),'recharge_order_id'=>$id,'user_id'=>$uid,'provider'=>'alipay','provider_trade_no'=>$o['provider_trade_no'],'amount_cents'=>$amount,'quota_to_recover'=>(int)$lot['paid_remaining'],'bonus_to_recover'=>(int)$lot['bonus_remaining'],'status'=>'requested','requested_by'=>null,'request_source'=>'user','user_reason'=>$reason?:null,'created_at'=>$now,'updated_at'=>$now]);});return redirect('/user/recharge?refund=requested');}catch(\Throwable $e){return response($e->getMessage(),422);}}
 public function cancel($id){if($g=$this->guard())return$g;$r=Db::name('refund_orders')->where('id',(int)$id)->where('user_id',$this->uid())->where('request_source','user')->where('status','requested')->find();if(!$r)return response('当前退款申请不可取消',422);Db::name('refund_orders')->where('id',$r['id'])->update(['status'=>'cancelled','failure_reason'=>'用户取消申请','updated_at'=>date('Y-m-d H:i:s')]);return redirect('/user/recharge?refund=cancelled');}
}
